import{_ as t,a}from"./chunks/14de6b489ced6c46358e.DtlC0L8T.js";import{_ as o,o as i,c as n,a6 as s}from"./chunks/framework.CnPv4DE1.js";const y=JSON.parse('{"title":"Become A Digital Renaissance Man (And Join The New Rich)","description":"","frontmatter":{"title":"Become A Digital Renaissance Man (And Join The New Rich)","search":false,"sidebar":false},"headers":[],"relativePath":"en/letters/become-a-digital-renaissance-man-and-join-the-new-rich.md","filePath":"en/letters/become-a-digital-renaissance-man-and-join-the-new-rich.md"}'),r={name:"en/letters/become-a-digital-renaissance-man-and-join-the-new-rich.md"};function l(h,e,p,c,d,u){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="become-a-digital-renaissance-man-and-join-the-new-rich" tabindex="-1">Become A Digital Renaissance Man (And Join The New Rich) <a class="header-anchor" href="#become-a-digital-renaissance-man-and-join-the-new-rich" aria-label="Permalink to &quot;Become A Digital Renaissance Man (And Join The New Rich)&quot;">​</a></h1><p>Dan Koe · 2023-02-11 · <a href="https://thedankoe.com/letters/become-a-digital-renaissance-man-and-join-the-new-rich/" target="_blank" rel="noreferrer">原文</a> · <a href="/letters/become-a-digital-renaissance-man-and-join-the-new-rich">返回中文译文</a></p><p><a href="https://www.youtube.com/embed/t82NzpIxKkc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p>When I was a child, I felt alone. I was a rebel.</p><p>I questioned almost everything that I was told to do whether it be going to church, after-school sports, or a 4-year college.</p><p>I am grateful for my programming, because it allowed me to get a leg up on my peers who listened and obeyed without question.</p><p>Formal education has its place, but people are losing trust in its ability to secure their future.</p><p>I would argue that they never had trust in its ability to secure a fulfilling future… But the option of ‘forging your own path’ seems even more uncertain. Why? Because it requires you to create certainty, not wait for someone else’s creation to be laid in front of you.</p><p>People inherently know that life enjoyment is a personal choice, but nobody wants to face that reality, so they outsource their quality of life to the exaggerated promises of schools and jobs.</p><p>It’s all too common for someone to spend 4-12 years and tens of thousands of dollars just to be placed in low-salary jobs that require a fraction of what they were taught in school.</p><p>It doesn’t stop there. Students often have to self-educate on the side if they want to advance in their career – so why not do that from the start?</p><p>The education system has its benefits, as all things do, but for those that want fulfilling work and an open schedule, a glorified piece of paper called a “degree” isn’t going to get you there.</p><p>It will be a stepping stone at best or a financial chain at worst.</p><p>After 5 years and 20 thousand dollars down the drain (with 2 more years to complete my degree), I was fed up.</p><p>There was a lot on the line, and the thought of getting a job was the bane of my existence.</p><p>I knew I could acquire the skill to avoid that reality.</p><p>I’m exaggerating here, of course.</p><p>Jobs are often a necessary step – but my conceptual survival was at stake.</p><p>I identified as someone who would never get a job, and my obsessive work reflected that. (I ended up getting a job, didn’t like that. It made me work 10x harder to get out).</p><p>In my final year, I took a class on basic computer programming.</p><p>This was the first class I was genuinely interested in after 4 years of trial and error.</p><p>It interested me so much that I spent 3-4 hours a day studying outside of class with online courses.</p><p>This is when the reality of formal education slapped me in the face.</p><p>Within 2 weeks, I learned the entirety of the college course curriculum through self-study on the internet.</p><p>I stopped going to class but still aced the tests.</p><h2 id="the-new-rich" tabindex="-1">The New Rich <a class="header-anchor" href="#the-new-rich" aria-label="Permalink to &quot;The New Rich&quot;">​</a></h2><p><img src="'+t+'" alt=""></p><p>We are in the middle of a massive shift.</p><p>But, this shift is not limited to money.</p><p>The New Rich isn’t about billions, mansions, and cars.</p><p>(I’m not saying these are bad. They can be useful goals for exposing yourself to life experience and developing a sense of mastery behind the skills used to get there).</p><p>The New Rich is about leveraging technology for fulfilling work, empty schedules, and individual choice.</p><p>Let’s break each down for the sake of awareness.</p><p>This section isn’t “hyper-actionable” and for good reason. You have to have the awareness of an idea before you can actualize it.</p><p>Hold each of these in your mind and correct your daily actions in alignment with them:</p><h3 id="technology" tabindex="-1">Technology <a class="header-anchor" href="#technology" aria-label="Permalink to &quot;Technology&quot;">​</a></h3><p>The internet has democratized wealth generation for the self-educated and self-reliant.</p><p>The internet allows you to learn skills that schools don’t teach, which are often the skills that lead to an irreplaceable income. If everyone is learning it, it’s replaceable. (But, don’t let a small internet echo chamber make you think that everyone is learning these modern skills, they aren’t.)</p><p>You need to invest time / money into education that won’t lead to a static salary.</p><p>Learn skills like marketing, sales, writing, and social media. Use those skills to build a one-person business.</p><p>Use no-code tools to create a service with your skill set, get results, and productize as you build an audience.</p><p>Invest time to get results. Use results as leverage.</p><h3 id="fulfilling-work" tabindex="-1">Fulfilling Work <a class="header-anchor" href="#fulfilling-work" aria-label="Permalink to &quot;Fulfilling Work&quot;">​</a></h3><p>Anyone can be happy, even the sheep, but fulfillment is a different story.</p><p>You need a purpose, or else you will be assigned one.</p><p>Life is not kind to those that don’t know what they want out of it.</p><p>But, this doesn’t happen in an instant.</p><p>Observe the masses and realize what you don’t want.</p><p>This will help you gain clarity on what you do want.</p><p>You need something to work towards, that will influence your daily decisions. The other option is to work towards someone else’s dreams for the sake of survival via paycheck.</p><h3 id="empty-schedules" tabindex="-1">Empty Schedules <a class="header-anchor" href="#empty-schedules" aria-label="Permalink to &quot;Empty Schedules&quot;">​</a></h3><p>With 1-2 years of fulfillment-directed effort by leveraging the internet, you will have control over your time, income, location, and lifestyle.</p><p>You won’t have a boss maintaining order in your daily schedule.</p><p>You will have to do that yourself.</p><p>8-hour workdays, endless screen time, and little movement are antagonists to human psychology and physiology.</p><p>You may not notice its ramifications if it is your normalized state of being. Control over your lifestyle allows you to realign with nature and feel superhuman.</p><h3 id="individual-choice" tabindex="-1">Individual Choice <a class="header-anchor" href="#individual-choice" aria-label="Permalink to &quot;Individual Choice&quot;">​</a></h3><p>Without autonomy, your choices are automatic for the sake of survival.</p><p>They stem from following the “secure” path that has been laid out for you.</p><p>Living in a constant state of survival is the cause of unnecessary stress.</p><p>Stress keeps your mind narrow.</p><p>It is difficult to make time for development, spirituality, and creativity if your choices are chained to a paycheck.</p><p>It’s not instant, as all good things aren’t, but creating an independent source of income is a necessity for those that want full control over their life.</p><h2 id="become-a-digital-renaissance-man" tabindex="-1">Become A Digital Renaissance Man <a class="header-anchor" href="#become-a-digital-renaissance-man" aria-label="Permalink to &quot;Become A Digital Renaissance Man&quot;">​</a></h2><p><img src="'+a+'" alt=""></p><p>The state of work has seen big changes since the pandemic.</p><p>Specialists are out, but so are generalists.</p><p>Now, they aren’t “out” entirely, of course.</p><p>You will be considered a specialist at times, a generalist at others. This is what the normal world runs on, but we aren’t here to be normal.</p><p>Specialist freelancers still have a cap on their income due to a lack of productization. Generalist agencies that can’t get above-average results for 95% of their clients.</p><p>We live in a time of specialized generalism.</p><p>That is to say, the highest-paid individuals are the ones that use the creative ability of their mind to focus on a specific, profitable problem to deliver above-average results.</p><p>The more skills you acquire and the more interests you research, the more awareness you have of the intersections of those domains.</p><p>You can pull from that experience to laser in on a problem related to any of those skills, interests, or combinations of both.</p><p>This has only become a possibility over the last decade thanks to the development of the internet.</p><p>History repeats itself, and we are cycling through a time where creatives, visionaries, and strategists have the resources available to them to thrive.</p><h3 id="acquire-evergreen-skills" tabindex="-1">Acquire Evergreen Skills <a class="header-anchor" href="#acquire-evergreen-skills" aria-label="Permalink to &quot;Acquire Evergreen Skills&quot;">​</a></h3><p>We’ve already discussed the <a href="https://thedankoe.com/the-1-million-dollar-skill-stack-learn-in-this-order/" target="_blank" rel="noreferrer">$1 Million Dollar Skill Stack</a> in previous letters.</p><p>So, to keep this brief, make it your purpose to obsess over marketing, sales, writing, and speaking.</p><p>If you have no idea what skills to commit your time to, make it these. <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Writing in a real-world setting</a> to gain experience will teach you more than reading endless books.</p><p>They all intersect, but they are necessary for any form of independent income generation.</p><p>To become a Digital Renaissance Man (or Woman), you will be learning a variety of skills and interests that pique your curiosity.</p><p>The evergreen skills allow you to package up and distribute those skills in a profitable manner.</p><p>A few YouTube videos will suffice in learning the fundamentals of these skills (don’t ask for recommendations, just go learn).</p><p>After, you must learn to apply those skills to whatever path you choose.</p><p>If you want to start freelancing or coaching, consider <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Modern Mastery</a>. If you want a masterclass of systems on becoming a creator (the embodiment of the Renaissance Man) consider <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Digital Economics</a>.</p><p>Courses aren’t necessary if you make the time to study, experiment, and fail. But, they are obviously helpful for those that want to streamline their efforts from somebody who has already done it.</p><h3 id="personal-interests" tabindex="-1">Personal Interests <a class="header-anchor" href="#personal-interests" aria-label="Permalink to &quot;Personal Interests&quot;">​</a></h3><p>What seems to be the only difference between the successful and mediocre in this age is choice of consumption.</p><p>In one camp we have the <em>distracted</em>.</p><p>They scroll without intention. No goals to focus their efforts.</p><p>In the other camp, we have the <em>obsessed</em>.</p><p>They research the interests that align with their future goals.</p><p>Those that are committed to building a physique of vitality and strength keep their finger on the pulse of the health industry.</p><p>Similar to those on their path to financial freedom. They are constantly experimenting with new methods – without attachment – to grow their brand.</p><p>The obsessed allow the roots of their mind to dig into the specific crevice of reality they cannot stop researching.</p><p>When this process is repeated over the years with new skills and interests, they open room for creative problem-solving.</p><h3 id="creative-problem-solving" tabindex="-1">Creative Problem Solving <a class="header-anchor" href="#creative-problem-solving" aria-label="Permalink to &quot;Creative Problem Solving&quot;">​</a></h3><p>1% of 50 years is 6 months, and most people can’t commit to the uncertain path for more than 2 weeks.</p><p>All of this takes time, a lot of time, and anyone that says otherwise isn’t looking out for your best interest. Only you can do that.</p><p>As you are pushing the boundaries of the known, finding fulfillment in the challenging problems that present themselves, and shining the light of awareness in the unknown, you increase the volume of your domain of mastery.</p><p>Here’s a thought experiment.</p><p>There are 4 small circles that form the outline of a square, each of them in four corners. These circles represent health, wealth, relationships, and happiness; the four eternal markets.</p><p>These are where all burning, and profitable, problems exist.</p><p>As you develop yourself within these domains, the circles increase in diameter until they begin to overlap like a venn diagram.</p><p>Each of these circles can be considered a field of awareness. You are aware of the problems within each domain and are able to piece together a creative solution from your experience.</p><p>Let’s set those aside for a minute and create a new set of circles.</p><p>This time, they represent the evergreen skills: writing, speaking, marketing, and sales.</p><p>The same thing happens. As you cultivate these skills, awareness overlaps and you can solve problems at the intersections while specialists are focused on one small circle.</p><p>Next, apply the same thing to results-oriented skills like social media, email marketing, graphic design, or programming.</p><p>As you learn one, two, three, or four applicable skills, because improvement never ends since entropy never sleeps, you begin to compound your creative problem-solving abilities.</p><p>We now have 3 sets of overlapping circles.</p><p>The last piece of this puzzle is personal interests.</p><p>Most people never have the thought of making a living doing what they love because they are missing awareness of the eternal markets, evergreen skills, and results-oriented skills that allow you to navigate the business landscape.</p><p>Now, any of the above can be considered personal interests of yours. Curiosity is powerful, and I would be disappointed if those skills did not excite you for a potential future. But, we can create one last square of circles that represents your personal interests.</p><p>In my case, I gravitated toward spirituality, philosophy, metaphysics, and human potential.</p><p>When I connect this last piece to the other 3 sets of squares we’ve created, it forms a three-dimensional cube, like a forcefield of connection.</p><p>We can place a problem in the middle of that cube, navigate the outer edges for creative firepower, and piece together a unique solution that may one day be worth millions of dollars.</p><p>Money, of course, is a byproduct of your life’s work.</p><p>Money matters, but there is a way to find meaning in this fabricated resource.</p><p>Your personal interests can be anything. Do not outsource your curiosity to me. The antagonist to your story is distraction and you must guard your mind.</p><p>Nothing happens, then everything happens.</p><p>When the outer edges of your multi-dimensional fields of awareness touch, it’s like the missing piece of an infinite puzzle.</p><p>At first, you can’t tell what the image is, but once the right piece clicks into place, you solidify a leap in understanding.</p><p>When the image of the puzzle is clear, you can observe the story of others, identify their missing piece, and help them fill the gap.</p><p>This is the path of the Digital Renaissance man.</p><p>They replace distraction with education, and while sustaining that habit, make focused effort toward helping others as you develop those skills.</p><p>Free, paid, in public, or in private. Freelancing, coaching, content creation, or whatever method you want to use to get your abilities in front of the world.</p><p>Skill must be tested with challenge.</p><p>If you do not make an effort to create with your skills as you acquire them, you are not acquiring skills.</p><p>That’s it.</p><p>Learn, act, repeat, and don’t let your mind get trapped in a thought loop of things that don’t matter.</p><p>– Dan</p><p>When you’re ready, here’s how I can help you.</p><p>2-Hour Writer gives you a real-world approach to creative writing. One that allows you to attract an audience, write with impact, and set yourself up for monetization. <a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">Enroll here.</a></p><p>Modern Mastery is a community and strategy library. If you want to meet the people that will push you into a better life, learn marketing, sales, social media, health, and performance, this is for you. <a href="https://modernmastery.co/letter" target="_blank" rel="noreferrer">Readers can join for $5.</a></p><p>Digital Economics is a masterclass for people that want to productize themselves. Learn and use my brand, content, product, and marketing systems to thrive in the future of work. <a href="https://digitaleconomics.school/" target="_blank" rel="noreferrer">Enroll here.</a></p>',137)])])}const g=o(r,[["render",l]]);export{y as __pageData,g as default};
